export interface TwinItem {
  id: string
  pairId: string
  level: DativeDrillLevel
  kind: 'verb-choice' | 'object-choice'
  prompt: string          // one ___ gap
  options: string[]       // exactly 2
  answers: string[]       // exactly 1
  translation: string
  explanation: string
}

